{
    public sealed class ReflectionFallProcess : IDisposable
    {
        private readonly ISourceEngineContext engine;
        private readonly Hook hook;
        public ReflectionFallProcess(ISourceEngineContext engine)
        {
            this.engine = engine;
            hook = new Hook(typeof(RoomPlayerSession).GetMethod(nameof(RoomPlayerSession.ReflectionFallCoroutine)), (Func<Func<RoomPlayerSession, IEnumerator>, RoomPlayerSession, IEnumerator>)Fall);
        }

        private IEnumerator Fall(Func<RoomPlayerSession, IEnumerator> original, RoomPlayerSession player)
        {
            if (!ReferenceEquals(player.EngineContext, engine))
                return original(player);
            return Wrapped(original, player);
        }

        private static IEnumerator Wrapped(Func<RoomPlayerSession, IEnumerator> original, RoomPlayerSession player)
        {
            var scene = (ISourceReflectionFallScene)player.Level;
            if (scene.ReflectionFallLevelSet == "Celeste")
            {
                var routine = original(player);
                while (routine.MoveNext())
                    yield return routine.Current;
                yield break;
            }

            player.Sprite.Play("bigFall");
            player.Data.Motion.Normal.Speed.Y = 0f;
            yield return null;
            scene.ShowReflectionFallEffects(true);
            player.Data.Motion.Normal.Speed.Y = 320f;
            while (!scene.CheckReflectionFallWater(player))
                yield return null;
            ((ISourceRumbleEnvironment)player.EngineContext).RumbleSession.Rumble(2, 1);
            scene.ShowReflectionFallEffects(false);
            player.Sprite.Play("bigFallRecover");
            yield return 1.2f;
            player.Machine.State = 0;
        }

        public void Dispose() => hook.Dispose();
    }
}

